skip_unless_full_tests()

# Expected values are SymPy's outputs for the same calls (sympy/polys/tests/test_appellseqs.py and test_polytools.py (gcdex_steps));
# the rows come from the battery that compares this port with SymPy.

test_that("appellseqs: bernoulli_poly matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(-1, x) })), "ERR ValueError: Cannot generate Bernoulli polynomial of index -1")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(0, x) })), "1")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(1, x) })), "x - 1/2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(2, x) })), "x^2 - x + 1/6")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(3, x) })), "x^3 - 3*x^2/2 + x/2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(4, x) })), "x^4 - 2*x^3 + x^2 - 1/30")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(5, x) })), "x^5 - 5*x^4/2 + 5*x^3/3 - x/6")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(6, x) })), "x^6 - 3*x^5 + 5*x^4/2 - x^2/2 + 1/42")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(7, x) })), "x^7 - 7*x^6/2 + 7*x^5/2 - 7*x^3/6 + x/6")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(8, x) })), "x^8 - 4*x^7 + 14*x^6/3 - 7*x^4/3 + 2*x^2/3 - 1/30")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(9, x) })), "x^9 - 9*x^8/2 + 6*x^7 - 21*x^5/5 + 2*x^3 - 3*x/10")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(10, x) })), "x^10 - 5*x^9 + 15*x^8/2 - 7*x^6 + 5*x^4 - 3*x^2/2 + 5/66")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(11, x) })), "x^11 - 11*x^10/2 + 55*x^9/6 - 11*x^7 + 11*x^5 - 11*x^3/2 + 5*x/6")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(12, x) })), "x^12 - 6*x^11 + 11*x^10 - 33*x^8/2 + 22*x^6 - 33*x^4/2 + 5*x^2 - 691/2730")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(15, x) })), "x^15 - 15*x^14/2 + 35*x^13/2 - 91*x^11/2 + 715*x^9/6 - 429*x^7/2 + 455*x^5/2 - 691*x^3/6 + 35*x/2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); bernoulli_poly(20, x) })), "x^20 - 10*x^19 + 95*x^18/3 - 323*x^16/2 + 6460*x^14/7 - 4199*x^12 + 41990*x^10/3 - 223193*x^8/7 + 45220*x^6 - 68723*x^4/2 + 219335*x^2/21 - 174611/330")
  expect_identical(.pyrun(local({ x <- Symbol("x"); as_expr(bernoulli_poly(5, x, polys = TRUE)) })), "x^5 - 5*x^4/2 + 5*x^3/3 - x/6")
  expect_identical(.pyrun(local({ bernoulli_poly(3) })), "_0^3 - 3*_0^2/2 + _0/2")
  expect_identical(.pyrun(local({ bernoulli_poly(4, Symbol("t")) })), "t^4 - 2*t^3 + t^2 - 1/30")
  expect_identical(.pyrun(local({ x <- Symbol("x"); subs(bernoulli_poly(6, x), x, 0) })), "1/42")
  expect_identical(.pyrun(local({ x <- Symbol("x"); subs(bernoulli_poly(7, x), x, 1) })), "0")
  expect_identical(.pyrun(local({ bernoulli_poly(4, Rational(1, 2)) })), "7/240")
})

