test_that("appellseqs: rel matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); expand(2^8 * bernoulli_poly(8, (x+1)/2)) - bernoulli_c_poly(8, x) })), "0")
  expect_identical(.pyrun(local({ x <- Symbol("x"); expand(2^9 * bernoulli_poly(9, (x+1)/2)) - bernoulli_c_poly(9, x) })), "0")
  expect_identical(.pyrun(local({ x <- Symbol("x"); expand(2 * (bernoulli_poly(8, x) - bernoulli_c_poly(8, x)) - genocchi_poly(8, x)) })), "0")
  expect_identical(.pyrun(local({ x <- Symbol("x"); expand(genocchi_poly(10, x) - euler_poly(9, x) * -10) })), "0")
})

test_that("gcdex_steps: steps matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^4 - 2*x^3 - 6*x^2 + 12*x + 15, x^3 + x^2 - 4*x - 4), .pyT) })), "[(0, 1, x^3 + x^2 - 4*x - 4), (1, 3 - x, x^2 + 4*x + 3), (3 - x, x^2 - 6*x + 10, 5*x + 5)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^5 + 2*x^4 - x^2 + 1, x^4 - 1), .pyT) })), "[(0, 1, x^4 - 1), (1, -x - 2, -x^2 + x + 3), (x^2 + x + 4, -x^3 - 3*x^2 - 6*x - 7, 7*x + 11), (x^3/7 - 11*x^2/49 + 10*x/49 - 23/49, -x^4/7 - 3*x^3/49 + 12*x^2/49 + 10*x/49 + 4/7, -51/49)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x*(x-1)*(x-2), (sym_I*x-1)*(x+1)), .pyT) })), "[(0, 1, I*x^2 + x*(-1 + I) - 1), (1, I*x + 1 - 4*I, x*(5 + 4*I) - 1 + 4*I), (x*(-4/41 - 5*I/41) - 35/1681 - 218*I/1681, x^2*(5/41 - 4*I/41) + x*(-766/1681 + 416*I/1681) + 774/1681 - 78*I/1681, -774/1681 + 78*I/1681)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^4 - y, x*(x^2 - y), gens = x), .pyT) })), "[(0, 1, x^3 - x*y), (1, -x, x^2*y - y), (-x/y, x^2/y + 1, x*(1 - y)), (-x^2/(y - 1) + 1, x^3/(y - 1) + x/(y - 1), -y)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^4 - y, x*(x^2 - y)), .pyT) })), "ERR ValueError: univariate polynomial expected")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^2*y - 2*x*y^2 + 1, x + 2*y, gens = x), .pyT) })), "[(0, 1, x + 2*y), (1, -x*y + 4*y^2, 8*y^3 + 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^2*y - 2*x*y^2 + 1, x + 2*y, gens = y), .pyT) })), "[(0, 1, x + 2*y), (1, -x^2 + x*y, 1 - x^3)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^3 + x^2 - 4*x - 4, x^4 - 2*x^3 - 6*x^2 + 12*x + 15), .pyT) })), "[(1, 0, x^3 + x^2 - 4*x - 4), (3 - x, 1, x^2 + 4*x + 3), (x^2 - 6*x + 10, 3 - x, 5*x + 5)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^2 - 1, x - 1), .pyT) })), "[(0, 1, x - 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^2 + 1, x^3), .pyT) })), "[(1, 0, x^2 + 1), (-x, 1, -x), (1 - x^2, x, 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^6 - 1, x^4 - 1), .pyT) })), "[(0, 1, x^4 - 1), (1, -x^2, x^2 - 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(2*x^2 + 4*x + 2, 4*x + 4), .pyT) })), "[(0, 1, 4*x + 4)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^3 - Rational(1, 2), 3*x^2 + x), .pyT) })), "[(0, 1, 3*x^2 + x), (1, 1/9 - x/3, x/9 - 1/2), (-27*x - 261/2, 9*x^2 + 81*x/2 - 27/2, 261/4)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x, x), .pyT) })), "[(0, 1, x)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x + 1, 3), .pyT) })), "[(0, 1, 3)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(12, 18), .pyT) })), "[(0, 1, 18), (1, 0, 12), (-1, 1, 6)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(240, 46), .pyT) })), "[(0, 1, 46), (1, -5, 10), (-4, 21, 6), (5, -26, 4), (-9, 47, 2)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(Rational(1, 2), Rational(3, 4)), .pyT) })), "[(0, 1, 3/4)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(17, 5), .pyT) })), "[(0, 1, 5), (1, -3, 2), (-2, 7, 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^8 + x^6 - 3*x^4 - 3*x^3 + 8*x^2 + 2*x - 5, 3*x^6 + 5*x^4 - 4*x^2 - 9*x + 21), .pyT) })), "[(0, 1, 3*x^6 + 5*x^4 - 4*x^2 - 9*x + 21), (1, 2/9 - x^2/3, -5*x^4/9 + x^2/9 - 1/3), (27*x^2/5 + 252/25, -9*x^4/5 - 54*x^2/25 + 81/25, -117*x^2/25 - 9*x + 441/25), (-25*x^4/39 + 625*x^3/507 - 115775*x^2/19773 + 3500*x/1521 - 50725/6591, 25*x^6/117 - 625*x^5/1521 + 3975*x^4/2197 - 250*x^3/507 + 7550*x^2/6591 + 125*x/169 - 50875/19773, 233150*x/19773 - 102500/6591), (-59319*x^5/233150 - 7296237*x^4/21743569 - 401016213*x^3/543589225 - 53090505*x^2/43487138 - 101811177*x/1087178450 + 192529701/1087178450, 19773*x^7/233150 + 2432079*x^6/21743569 + 102938238*x^5/543589225 + 14454063*x^4/43487138 - 97757712*x^3/543589225 - 426681567*x^2/1087178450 - 7553286*x/108717845 - 76897197/1087178450, -1288744821/543589225)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^2 + y^2, x + y, x), .pyT) })), "[(0, 1, x + y), (1, -x + y, 2*y^2)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^2 + y^2, x + y, y), .pyT) })), "[(0, 1, x + y), (1, x - y, 2*x^2)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^3 - x, x^2 + sqrt(Integer(2))*x), .pyT) })), "ERR ValueError: univariate polynomial expected")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lapply(gcdex_steps(x^4 + 1, x^2 + sym_I), .pyT) })), "[(0, 1, x^2 + I)]")
